<script setup>
import {ref,computed,watch} from 'vue'
const props=defineProps({works:{type:Array,required:true}})
const dialog=ref(null),project=ref(0),shot=ref(0),active=ref(0)
const work=computed(()=>props.works[active.value])
const tabLabels=['铝加工','食品饮料灌装厂','炭素','煤化工']
function moveTab(index,event){active.value=(index+props.works.length)%props.works.length;event.currentTarget.parentElement.children[active.value].focus()}
const selected=computed(()=>props.works[project.value])
const summaries=['覆盖铝热轧与冷轧产线的工业数字孪生项目。','食品饮料产线的三维场景与运行界面展示。','预焙阳极厂区与物料流转的三维可视化项目。','煤制甲醇厂区、设备与管廊的数字孪生展示。']
const slide=ref(0)
watch(active,()=>{slide.value=0})
const position=j=>{const n=work.value.gallery.length;const d=(j-slide.value+n)%n;return d===0?'center':d===1?'next':d===n-1?'previous':'hidden'}
function advance(step){slide.value=(slide.value+step+work.value.gallery.length)%work.value.gallery.length}
function selectSlide(j){if(j===slide.value)open(active.value,j);else slide.value=j}
function open(i,image){project.value=i;shot.value=image;dialog.value.showModal()}
function change(step){shot.value=(shot.value+step+selected.value.gallery.length)%selected.value.gallery.length}
</script>
<template>
 <div class="industrial-projects">
  <div class="industrial-tabs" role="tablist" aria-label="选择工业数字孪生项目"><button v-for="(item,i) in works" :key="item.title" :id="`industrial-tab-${i}`" role="tab" :aria-selected="active===i" aria-controls="industrial-project-panel" :tabindex="active===i?0:-1" @click="active=i" @keydown.right.prevent="moveTab(i+1,$event)" @keydown.left.prevent="moveTab(i-1,$event)" @keydown.home.prevent="moveTab(0,$event)" @keydown.end.prevent="moveTab(works.length-1,$event)"><small>0{{i+1}}</small>{{tabLabels[i]}}</button></div>
  <article :key="work.title" id="industrial-project-panel" class="industrial-board" role="tabpanel" :aria-labelledby="`industrial-tab-${active}`">
   <div class="board-heading"><span class="board-number">0{{active+1}}</span><div><h4>{{work.title}}</h4><p>{{summaries[active]}}</p></div><span class="board-category">DIGITAL TWIN <small>{{work.gallery.length}} 张项目画面</small></span></div>
   <div class="industrial-carousel" role="region" aria-roledescription="轮播" :aria-label="work.title+'项目图片'" tabindex="0" @keydown.left.prevent="advance(-1)" @keydown.right.prevent="advance(1)">
    <div class="carousel-stage"><button v-for="(image,j) in work.gallery" :key="image.src" class="carousel-slide" :class="'slide-'+position(j)" :tabindex="position(j)==='hidden'?-1:0" :aria-hidden="position(j)==='hidden'" @click="selectSlide(j)" :aria-label="j===slide?'放大当前项目图片':'切换到'+image.label"><img :src="image.src" :alt="work.title+' · '+image.label" loading="lazy" draggable="false"><span v-if="j===slide" class="carousel-enlarge">查看大图 ↗</span></button><button class="carousel-side-arrow arrow-left" @click="advance(-1)" aria-label="上一张工业项目画面">←</button><button class="carousel-side-arrow arrow-right" @click="advance(1)" aria-label="下一张工业项目画面">→</button></div>
    <div class="carousel-controls"><span aria-live="polite">{{String(slide+1).padStart(2,'0')}} <small>/ {{String(work.gallery.length).padStart(2,'0')}}</small></span></div>
   </div>
  </article>
  <dialog ref="dialog" class="industrial-dialog" @click="$event.target===dialog&&dialog.close()" @keydown.left.prevent="change(-1)" @keydown.right.prevent="change(1)">
   <template v-if="selected"><div class="industrial-dialog-head"><div><small>INDUSTRIAL PROJECT</small><h4>{{selected.title}}</h4></div><button @click="dialog.close()" aria-label="关闭项目图片">关闭 ×</button></div><img class="industrial-detail" :src="selected.gallery[shot].src" :alt="selected.title+' · '+selected.gallery[shot].label"><div class="industrial-dialog-controls"><button @click="change(-1)" aria-label="上一张项目图片">← 上一张</button><span>{{shot+1}} / {{selected.gallery.length}}</span><button @click="change(1)" aria-label="下一张项目图片">下一张 →</button></div></template>
  </dialog>
 </div>
</template>
